CREATE TABLE IF NOT EXISTS contract_policies (job_id BIGINT UNSIGNED PRIMARY KEY, signature_method VARCHAR(20) NOT NULL DEFAULT 'internal', required_before_deployment TINYINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS contract_document_requirements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, job_id BIGINT UNSIGNED NOT NULL, document_type VARCHAR(120) NOT NULL, UNIQUE KEY uq_contract_requirement(job_id,document_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS employment_contracts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, application_id BIGINT UNSIGNED NOT NULL, revision INT NOT NULL, title VARCHAR(190) NOT NULL, terms MEDIUMTEXT NOT NULL, content_hash CHAR(64) NOT NULL, method VARCHAR(20) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'draft', expires_at DATETIME NOT NULL, created_by BIGINT UNSIGNED NOT NULL, approved_by BIGINT UNSIGNED NULL, issued_at DATETIME NULL, signed_at DATETIME NULL, signer_user_id BIGINT UNSIGNED NULL, signer_name VARCHAR(190) NULL, envelope_id VARCHAR(100) NULL, provider_transaction_id CHAR(36) NULL, provider_error VARCHAR(100) NULL, signature_page INT NOT NULL DEFAULT 1, signature_x INT NOT NULL DEFAULT 40, signature_y INT NOT NULL DEFAULT 60, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_contract_revision(application_id,revision), UNIQUE KEY uq_envelope(envelope_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS contract_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, contract_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NULL, action VARCHAR(60) NOT NULL, details_json MEDIUMTEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX ix_contract_event(contract_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS contract_files (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, contract_id BIGINT UNSIGNED NOT NULL, kind VARCHAR(25) NOT NULL, storage_name CHAR(64) NOT NULL, file_hash CHAR(64) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_contract_file(contract_id,kind)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS docusign_connect_events (payload_hash CHAR(64) PRIMARY KEY, envelope_id VARCHAR(100) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', attempts INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
